window.RP_SESSION={"id":"S-d82ef80d718b","messages":[{"id":"RP-III-0092162","time":"2026-05-06T01:20:00+09:00","room":"RP III","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"불로 미래를 점지한다. 꽤나 웃긴 이야기지만, 모종의 이유로 그것을 시험하던 어린 날의 솔은.\n\n이것이 제법 믿을만한 것임을 깨달았다.","characters":["P-e2f54d3db7fa"]},{"id":"RP-III-0092163","time":"2026-05-06T01:21:00+09:00","room":"RP III","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"일렁이는 불빛은 점점 빛을 잃어가다. 짙푸른 재를 남겼다.\n\n···\n\n고이 잘 길을 찾고 나아가기를.","characters":["P-e2f54d3db7fa"]},{"id":"RP-III-0092164","time":"2026-05-06T01:23:00+09:00","room":"RP III","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"부디 영웅적인 누군가의 이야기를 기억할 자가 있기를.\n\n어두운 하늘 속에서도 말갛게 빛나는 새하얀 구름이 되기를.\n\n짙은 숲 속에서 든든한 이정표가 되어줄 나무가 되기를.","characters":["P-e2f54d3db7fa"]},{"id":"RP-III-0092165","time":"2026-05-06T01:24:00+09:00","room":"RP III","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"솔은 알고 있었다.\n\n다시금 자연의 순환에 따르러 돌아간 그 존재가\n\n자연에게 사랑받을 것을.","characters":["P-e2f54d3db7fa"]},{"id":"RP-III-0092166","time":"2026-05-06T01:24:00+09:00","room":"RP III","name":"솔 세크메트","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-e2f54d3db7fa"]},{"id":"RP-III-0092167","time":"2026-05-06T01:24:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
